import { createBrowserPeer } from '@migaia/rpc-browser'

/** 与 Worker 保持一致的业务接口。 */
type ISharedApi = {
  ping(): string
  note(value: string): void
  count(limit: number): AsyncIterableIterator<number>
}
/** 页面创建原生 Worker，并保留关闭其端口的责任。 */
